export const OVERLAYS = {"practrum--cow-restraint":{"practrum--cow-restraint--low-stress-handling-temple-grandin":{"claims":[{"id":"practrum--cow-restraint--low-stress-handling-temple-grandin--v1","statement":"Point of balance อยู่ที่หัวไหล่ของสัตว์ ผู้จับบังคับควรยืนด้านหลัง point of balance เพื่อให้สัตว์เดินไปข้างหน้า และยืนด้านหน้า point of balance เพื่อให้สัตว์ถอยหลัง","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Article 7.5.1. General principles, point 3 (Animal behaviour)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Animal handlers should use the point of balance at the animal's shoulder to move animals, adopting a position behind the point of balance to move an animal forward and in front of the point of balance to move it backward."}},{"id":"practrum--cow-restraint--low-stress-handling-temple-grandin--v2","statement":"ขนาดของ flight zone ไม่คงที่ ขึ้นกับชนิดสัตว์ ตัวสัตว์แต่ละตัว และประสบการณ์ที่เคยสัมผัสกับคน สัตว์ที่เลี้ยงใกล้ชิดคน (tame) มี flight zone เล็กกว่า ส่วนสัตว์ที่เลี้ยงปล่อยหรือระบบ extensive อาจมี flight zone ตั้งแต่ 1 เมตรจนถึงหลายเมตร และผู้จับบังคับควรเลี่ยงการรุกล้ำ flight zone อย่างฉับพลันเพราะอาจทำให้สัตว์ตื่นตกใจ ก้าวร้าว หรือพยายามหนี","evidenceStatus":"expert-consensus","reviewStatus":"verified","sourceRefs":[{"sourceId":"guide-world-organisation-for-2022","locator":"Article 7.5.1. General principles, point 3 (Animal behaviour)","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"This critical distance, which defines the flight zone, varies among species and individuals of the same species, and depends upon previous contact with humans. Animals reared in close proximity to humans i.e. tame have a smaller flight zone"}},{"id":"practrum--cow-restraint--low-stress-handling-temple-grandin--v3","statement":"การปรับคอกเพียงเล็กน้อย (บังสายตาโคเมื่อผู้จับบังคับเดินเข้าไปลึกใน flight zone และกำจัดวัตถุสว่าง คู่สีตัดกัน เงา และแอ่งน้ำ) ร่วมกับ good handling practices (เลิกใช้สุนัข เลิกใช้ไม้ไฟฟ้า เลิกตะโกน) ลดการหลั่ง cortisol ในแม่โค Nellore ได้จริง จาก 60.40 ± 3.8 เหลือ 41.03 ± 2.9 ng/mL (P < 0.001)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29139068","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The cortisol release was lower (P < 0.001) and better for the improved methods, resulting in calmer cows compared to cortisol released before the minor changes (41.03 ± 2.9 vs 60.40 ± 3.8 ng/mL)."}},{"id":"practrum--cow-restraint--low-stress-handling-temple-grandin--v4","statement":"ในฟาร์มโคนมเชิงพาณิชย์ การที่ผู้เลี้ยงใช้ negative หรือ forceful tactile interactions กับโคมาก สัมพันธ์เชิงลบกับ milk yield, protein และ fat ของฟาร์ม (r = -0.36, -0.35 และ -0.33 ตามลำดับ, P < 0.01) และสัมพันธ์เชิงบวกกับความเข้มข้นของ cortisol ในน้ำนม (r = 0.34, P < 0.01)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11063304","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the use of negative interactions by stockpeople was significantly and negatively correlated with milk yield, protein, and fat at the farm (r = -0.36, -0.35 and -0.33, respectively, df = 64, P < 0.01) and was significantly and positively cor"}}]},"practrum--cow-restraint--halter-standing-restraint":{"claims":[{"id":"practrum--cow-restraint--halter-standing-restraint--v1","statement":"ความปลอดภัยขณะเข้าใกล้และจับบังคับโคขึ้นกับความรู้เรื่อง flight zone ร่วมกับการเลือกใช้เครื่องมือและอุปกรณ์ restraint ที่เหมาะสม ซึ่งเป็นแนวทางลดการบาดเจ็บของผู้ปฏิบัติงานในฟาร์มโคนม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-23844794","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Care when in close proximity to the animal is the key for safe handling, including knowledge of the flight zone, and use of the right types of tools and suitable restraint equipment."}}]},"practrum--cow-restraint--casting-methods-recumbent":{"claims":[{"id":"practrum--cow-restraint--casting-methods-recumbent--v1","statement":"ในโค 125 ตัวที่ถูกวางยาสลบด้วย xylazine/halothane จนอยู่ในภาวะ recumbent พบภาวะแทรกซ้อนจากการวางยา 10 ตัว (8%) ซึ่งส่วนใหญ่สัมพันธ์กับ regurgitation ของ ruminal contents โดยมีหรือไม่มี aspiration ร่วมด้วย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17422450","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Anesthetic complications were recorded for ten cattle (8%) in the series and were mainly associated with regurgitation of ruminal contents, with or without aspiration."}}]}},"practrum--dehorning":{"practrum--dehorning--anatomy-anesthesia":{"claims":[{"id":"practrum--dehorning--anatomy-anesthesia--v1","statement":"Cornual nerve block ด้วย lignocaine ทำให้ escape behaviour ระหว่าง disbudding และ dehorning หายไปเกือบหมด และลด plasma cortisol response ต่อ dehorning ได้ประมาณ 2 ชั่วโมง หลังจากนั้นจะเกิด delayed cortisol response ขึ้นอีกนานราว 6 ชั่วโมง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15848777","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A cornual nerve blockade using lignocaine virtually eliminates the escape behaviour seen during disbudding and dehorning and reduces the plasma cortisol response to dehorning for about 2 h. Thereafter there is an increase in the plasma cort"}},{"id":"practrum--dehorning--anatomy-anesthesia--v2","statement":"การให้ regional analgesia ร่วมกับ NSAID (ketoprofen) ในลูกโคที่ทำ dehorning ทำให้ plasma cortisol ใกล้เคียงกับกลุ่มควบคุมที่ไม่ได้ dehorn และต่ำกว่ากลุ่มที่ได้ regional analgesia อย่างเดียวอย่างมีนัยสำคัญ จึงควรใช้ systemic analgesic ร่วมกับ regional analgesia เสมอ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9625471","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"When animals were given a regional analgesic and ketoprofen the plasma cortisol concentrations were similar to control animals which had not been dehorned, with a small increase in plasma cortisol concentrations for the first hour after deh"}},{"id":"practrum--dehorning--anatomy-anesthesia--v3","statement":"การเสริม xylazine sedation (0.2 mg/kg IM) เข้ากับ lidocaine cornual nerve block และ meloxicam ในลูกโคที่ทำ cautery disbudding ลดการดิ้นระหว่างทำหัตถการ โดยลูกโคที่ไม่ได้รับยาซึมมี odds ของการดิ้นมากกว่า 2 ครั้ง เป็น 4.5 เท่า (95% CI 1.5-13.2) ของลูกโคที่ได้รับยาซึม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33685706","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Nonsedated calves had 4.5 times the odds (95% CI: 1.5-13.2) of struggling more than twice during the disbudding procedure compared with sedated calves, and it took less time to administer a nerve block to sedated calves compared with nonsed"}}]},"practrum--dehorning--disbudding-methods-comparison":{"claims":[{"id":"practrum--dehorning--disbudding-methods-comparison--v1","statement":"Caustic paste disbudding ทำให้เจ็บเฉียบพลันนานอย่างน้อย 180 นาที ซึ่งลดลงได้ด้วย cornual nerve block ผู้วิจัยจึงแนะนำให้ลูกโคที่ทำ caustic paste ได้รับทั้ง local anaesthetic แบบ cornual nerve block และ NSAID","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28551190","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Caustic paste appears to be acutely painful for at least 180 min, and this is reduced by a cornual nerve block but not by our novel paste. ... We recommend that calves disbudded with caustic paste receive local anesthetic with a cornual ner"}},{"id":"practrum--dehorning--disbudding-methods-comparison--v2","statement":"แผลจาก caustic paste disbudding หายช้ามาก โดยใช้เวลาหายสนิทเฉลี่ย 18.8 ± 6 สัปดาห์ (พิสัย 8.7-34.1 สัปดาห์) ซึ่งนานประมาณ 2 เท่าของแผลจากวิธี cautery ที่มีรายงานไว้ และแผลยังไวต่อความเจ็บมากกว่าเนื้อเยื่อปกติอย่างน้อย 6 สัปดาห์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-37268589","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In conclusion, caustic paste disbudding wounds took 18.8 wk to fully heal and were more sensitive than intact horn buds for 6 wk. ... take twice as long to heal compared with cautery methods described in the literature."}}]},"practrum--dehorning--post-op-complication-sinusitis":{"claims":[{"id":"practrum--dehorning--post-op-complication-sinusitis--v1","statement":"Chronic frontal sinusitis ในโคนมส่วนใหญ่มีประวัติ dehorning ที่เปิดเข้าไปถึง frontal sinus (67% ของ 12 ราย) การรักษาคือ trephination 2 ตำแหน่งเพื่อ drainage และ lavage โพรงไซนัส ร่วมกับยาปฏิชีวนะและยาแก้ปวด โดยการระบายหนองออกเป็นสิ่งจำเป็นเพื่อป้องกันการลุกลามเข้าสู่ระบบประสาทส่วนกลาง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1500335","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Chronic frontal sinusitis in 12 dairy cattle most often was associated with a history of dehorning, in which the sinus was entered (67%), or with respiratory tract disease (25%). ... Treatment consisted of trephination at 2 sites, drainage "}}]},"practrum--dehorning--method-by-age":{"claims":[{"id":"practrum--dehorning--method-by-age--v1","statement":"วิธีเอาเขาออกแปรตามอายุจริงในทางปฏิบัติ จากการสำรวจฟาร์มโคนม 217 ราย caustic paste เป็นวิธีหลัก (61% ของผู้ตอบ) และ 53% ทาในวันที่ลูกโคเกิด, hot iron (32%) ทำมากที่สุดช่วง 4-8 wk (41%) และ 1-4 wk (33%) ส่วน surgical method (gouge, scoop, wire saw) 73% ทำเมื่ออายุ 8 wk ขึ้นไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-34364646","locator":"104(11):11995-12008","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most respondents (61%) used caustic paste as their primary method, which was most commonly applied on the day the calf was born (53%). Hot iron was used by 32% of respondents, and surgical methods (gouge, scoop, or wire saw) were used by 6%"}},{"id":"practrum--dehorning--method-by-age--v2","statement":"เหตุผลที่ต้อง disbud ตั้งแต่เล็กแทนการ dehorn ตอนโตคือความเจ็บ: cortisol response ต่อ cautery disbudding ต่ำกว่า amputation dehorning อย่างมีนัยสำคัญ ซึ่งบ่งว่า amputation dehorning เจ็บกว่า และเพื่อบรรเทาปวดให้ดีที่สุดควรใช้ xylazine sedation + local anaesthesia + NSAID ร่วมกันในทั้งสองวิธี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-15848777","locator":"169(3):337-49","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The cortisol response to cautery disbudding is significantly smaller than that to amputation dehorning which infers that the latter is more painful... Cautery disbudding is preferable to amputation dehorning, but for optimal pain relief xyl"}},{"id":"practrum--dehorning--method-by-age--v3","statement":"ในฟาร์มโคนม 639 แห่งที่สำรวจ ฟาร์มที่เอาเขาออกใช้วิธี disbudding ทั้งหมด โดย hot-iron cauterization เป็นวิธีที่นิยมที่สุด (91%) และทำที่อายุเฉลี่ย 32 วัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22032397","locator":"94(11):5724-34","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The outcomes of the study showed that dehorning was carried out on 80% of the surveyed farms, and disbudding was the method reported by all the interviewed farmers. Hot-iron cauterization was the preferred method for disbudding (91%). On av"}}]},"practrum--dehorning--decision-tree-when-to-dehorn-vs-not":{"claims":[{"id":"practrum--dehorning--decision-tree-when-to-dehorn-vs-not--v1","statement":"เหตุผลที่รองรับการ dehorn คือความปลอดภัยของผู้ปฏิบัติงานและการลดความเสี่ยงบาดเจ็บระหว่างโคในฝูง ส่วนฟาร์มที่เลือกเก็บเขาไว้ให้เหตุผลด้านความสวยงามเป็นหลัก (54%) รองลงมาคือไม่มีเวลา (24%) และ 74% ของกลุ่มนี้รายงานว่าไม่มีปัญหาในการจัดการโคที่มีเขา","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22032397","locator":"94(11):5724-34","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Calf dehorning is a routine husbandry practice on dairy farms that is justified by safety reasons for stockpersons and by a reduced risk of injures among herdmates... Aesthetic motivations (54% of respondents) and lack of time (24%) were th"}},{"id":"practrum--dehorning--decision-tree-when-to-dehorn-vs-not--v2","statement":"Disbudding และ dehorning ทำเพื่อป้องกันการบาดเจ็บของทั้งสัตว์และคน แต่เป็นหัตถการที่ไม่พึงประสงค์ มีต้นทุน และถูกจับตามากขึ้นในแง่ animal welfare ทางเลือกที่ตัดความจำเป็นในการเอาเขาออกทั้งหมดคือการคัดเลือกพันธุ์ polled เพราะ horn เป็น recessively inherited trait แต่การนำไปใช้ยังจำกัดเพราะพ่อพันธุ์ polled มี genetic merit ต่ำและหายาก (มีนาคม 2018 มีพ่อพันธุ์ homozygous polled ที่ active ขึ้นทะเบียนกับ NAAB เพียง 3 ตัวใน Holstein และ 0 ตัวใน Jersey)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30852022","locator":"102(5):4215-4226","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Disbudding and dehorning are commonly used cattle management practices to protect animals and humans from injury. They are unpleasant, costly processes subject to increased public scrutiny as an animal welfare issue. Horns are a recessively"}}]}},"practrum--hoof-trim":{"practrum--hoof-trim--routine-care-disease-categories":{"claims":[{"id":"practrum--hoof-trim--routine-care-disease-categories--v1","statement":"การแต่งกีบปีละ 2 ครั้ง (เพิ่มการแต่งกีบช่วงฤดูใบไม้ร่วงจากที่แต่งฤดูใบไม้ผลิอยู่แล้ว) ลด odds ของ lameness เหลือ 0.66 และลด odds ของ sole ulcer เหลือ 0.59 เมื่อตรวจในการแต่งกีบครั้งถัดไป และลดความจำเป็นในการรักษากีบแบบเฉียบพลันระหว่างรอบ (OR 2.02 ในกลุ่มที่ไม่แต่ง)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12069775","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"AT cattle at spring trimmings had significantly lower odds of lameness (OR=0.66) and of haemorrhages of the sole or white-line (OR=0.86), sole ulcer (OR=0.59) and white-line fissure or double sole (OR=0.71)-but not of moderate-to-severe hee"}},{"id":"practrum--hoof-trim--routine-care-disease-categories--v2","statement":"Digital dermatitis มีสาเหตุสัมพันธ์กับ Treponema โดยตรวจพบ BDD-associated Treponema phylogroup อย่างน้อย 1 กลุ่มใน 100% ของรอยโรค BDD (Treponema medium/vincentii-like 79%, Treponema phagedenis-like 91%, Treponema pedis 71%) ขณะที่ไม่พบ DNA ของ treponeme กลุ่มนี้เลยในเนื้อเยื่อกีบปกติ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25937315","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"One or more BDD-associated Treponema phylogroups were detected in 100% of beef BDD lesions. \"Treponema medium/Treponema vincentii-like\", \"Treponema phagedenis-like\" and Treponema pedis spirochetes were identified in 27/34 (79%), 31/34 (91%)"}},{"id":"practrum--hoof-trim--routine-care-disease-categories--v3","statement":"Fusobacterium necrophorum subspecies necrophorum เป็นเชื้อหลักของ interdigital phlegmon (foot rot) ในโคนม และตัวอย่างจากรอยโรคระยะเฉียบพลันส่วนใหญ่ (66.7%) พบทั้ง F. necrophorum และ Dichelobacter nodosus ร่วมกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30696445","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Most of the samples of acute IP (66.7%) harboured both F. necrophorum and D. nodosus. ... Our result confirms that F. necrophorum subspecies necrophorum is the main pathogen in IP, but also T. pyogenes is associated with the healing stage o"}}]},"practrum--hoof-trim--hoof-anatomy-claw-zones":{"claims":[{"id":"practrum--hoof-trim--hoof-anatomy-claw-zones--v1","statement":"Sole ulcer (pododermatitis circumscripta) พบบ่อยที่สุดที่ lateral claw ของขาหลัง มักเกิดทั้งสองข้าง มีอัตราการกลับเป็นซ้ำสูง และตำแหน่งที่รายงานบ่อยที่สุดคือรอยต่อระหว่าง axial heel กับ sole การรักษาคือ corrective trimming ร่วมกับการลดการรับน้ำหนักที่กีบนั้น","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16955800","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"They are found most commonly in the hind lateral claw, are frequently bilateral, and have a high rate of reoccurrence. ... Sole ulcers tend to occur in specific locations; the most reported site is the junction of the axial heel and sole. ."}},{"id":"practrum--hoof-trim--hoof-anatomy-claw-zones--v2","statement":"กลไกของ sole ulcer คือ suspensory structures ของ distal phalanx อ่อนแอลง ทำให้ distal phalanx (P3) จมลงใน claw capsule แล้ว tuberculum flexorium กด sole epidermis และ dermis จนเกิดเลือดออกและสร้าง horn ผิดปกติ ปรากฏเป็นเนื้อกีบสีเหลืองแดงและนิ่มที่ region 4 ของ sole","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38825113","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pododermatitis aseptica hemorrhagica circumscripta is associated with metalloproteinase 2 weakening of distal phalangeal suspensory structures and sinkage of the distal phalanx in the claw capsule. Pressure from the tuberculum flexorium on "}}]},"practrum--hoof-trim--digital-amputation-s2-sole-ulcer-osteomyelitis":{"claims":[{"id":"practrum--hoof-trim--digital-amputation-s2-sole-ulcer-osteomyelitis--v1","statement":"Septic arthritis ของ distal interphalangeal joint เป็นข้อบ่งชี้ของ digital amputation ในโค และในการศึกษาแบบสุ่มเปรียบเทียบ digital amputation กับ joint resection ในโคนม 52 ตัว ระดับความเจ็บขา (lameness) ดีขึ้นเร็วกว่าอย่างมีนัยสำคัญหลัง digital amputation แม้ค่าเฉลี่ยอายุการใช้งานหลังผ่าตัดจะไม่ต่างกัน (13.5 เทียบกับ 10.9 เดือน)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17547598","locator":"","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"After surgery, degree of lameness improved significantly faster after DAMP than after JRES. ... Mean life span between groups was not significantly different (DAMP=13.5 months, JRES=10.9 months)."}}]}},"practrum--bovine-anesthesia":{"practrum--bovine-anesthesia--local-anesthesia-lidocaine-2":{"claims":[{"id":"practrum--bovine-anesthesia--local-anesthesia-lidocaine-2--v1","statement":"Caudal epidural ในโคฉีดที่ sacrococcygeal intervertebral space (S5-Co1) หรือ first intercoccygeal space (Co1-Co2) ซึ่งเป็นสองตำแหน่งที่ใช้บ่อยที่สุด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28096620","locator":"Vet World 2016;9(12):1450-1455, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most common sites for epidural administration in cattle, camels, and buffalos were the sacrococcygeal intervertebral space (S5-Co1) and first intercoccygeal intervertebral space (Co1-Co2)."}},{"id":"practrum--bovine-anesthesia--local-anesthesia-lidocaine-2--v2","statement":"ขนาด lidocaine ที่ใช้บ่อยที่สุดสำหรับ epidural ในโคตามการทบทวนวรรณกรรมคือ 0.22-0.5 mg/kg","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28096620","locator":"Vet World 2016;9(12):1450-1455, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most frequently used drugs and dosages were lidocaine (0.22-0.5 mg/kg), bupivacaine (0.125 mg/kg), ropivacaine (0.11 mg/kg), xylazine (0.05 mg/kg)"}},{"id":"practrum--bovine-anesthesia--local-anesthesia-lidocaine-2--v3","statement":"Paravertebral block ทั้งแบบ proximal และ distal มีเป้าหมายที่ spinal nerves T13, L1 และ L2 เพื่อให้ระงับความรู้สึกบริเวณ flank สำหรับผ่าตัดท่ายืน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27805442","locator":"Am J Vet Res 2016;77(11):1187-1193, abstract (Procedures and Results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A suitable acoustic window was identified to facilitate access to the T13, L1, and L2 spinal nerves in cadavers and live calves... In calves, the UGPNB, DPNB, and PPNB reduced the withdrawal response to the noxious stimulus, mainly in the d"}}]},"practrum--bovine-anesthesia--sedation-alpha-2-agonist":{"claims":[{"id":"practrum--bovine-anesthesia--sedation-alpha-2-agonist--v1","statement":"โคเกิด sedation จาก xylazine ที่ขนาดต่ำกว่าขนาดที่ต้องใช้ในสัตว์ชนิดอื่นมาก จึงต้องระวังเรื่อง species sensitivity","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-525899","locator":"Am J Vet Res 1979;40(12):1777-1780, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sedation by xylazine is produced in cattle at doses which are small compared to those which is required for sedation in other species."}},{"id":"practrum--bovine-anesthesia--sedation-alpha-2-agonist--v2","statement":"Xylazine ขนาด sedative ในลูกโคทำให้ heart rate, cardiac output และ arterial blood pressure ลดลง ขณะที่ total peripheral resistance เพิ่มขึ้น โดยการศึกษานี้ไม่พบ hypertensive response","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-525899","locator":"Am J Vet Res 1979;40(12):1777-1780, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These effects included immediate and prolonged reductions in heart rate, cardiac output, arterial blood pressure, and left ventricular dp/dt max... Total peripheral resistance, end-diastolic left ventricular pressure, end-diastolic left ven"}},{"id":"practrum--bovine-anesthesia--sedation-alpha-2-agonist--v3","statement":"Atipamezole 30 microgram/kg IV กลับฤทธิ์ xylazine ในลูกโคได้ทั้ง sedation, bradycardia และ ruminal atony จึงใช้เป็น antidote เมื่อได้ xylazine เกินขนาด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1681769","locator":"Am J Vet Res 1991;52(8):1265-1268, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Atipamezole given at dosages of 10 and 30 micrograms/kg reversed xylazine-induced ruminal atony in a dose-dependent manner. In addition, 30 micrograms of atipamezole/kg reversed xylazine-induced bradycardia, but the lower dosages of this an"}}]},"practrum--bovine-anesthesia--block-decision-tree-clinical-scenario":{"claims":[{"id":"practrum--bovine-anesthesia--block-decision-tree-clinical-scenario--v1","statement":"หัตถการผ่าตัดในสัตว์เคี้ยวเอื้องหลายอย่างทำได้อย่างปลอดภัยและ humane โดยใช้ physical restraint + mild sedation + local/regional/spinal anesthesia แทน general anesthesia และเลือก block ให้ตรงกับหัตถการ (dehorning, หัตถการจมูกและตา, laparotomy, หัตถการระบบสืบพันธุ์, teat repair, หัตถการที่ distal limb)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27719762","locator":"32(3):535-552","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Local, regional, and spinal anesthesias are safe, effective, often more desirable procedures for ruminants than general anesthesia. Many procedures can be performed safely and humanely in ruminants using a combination of physical restraint,"}},{"id":"practrum--bovine-anesthesia--block-decision-tree-clinical-scenario--v2","statement":"Caudal epidural ในโคฉีดที่ sacrococcygeal intervertebral space (S5-Co1) หรือ first intercoccygeal space (Co1-Co2) โดย lidocaine ที่ใช้บ่อยที่สุดในวรรณกรรมคือ 0.22-0.5 mg/kg และใช้คุมปวดสำหรับหัตถการบริเวณหาง ทวารหนัก vulva perineum เต้านมส่วนท้าย scrotum และขาหลังส่วนบน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-28096620","locator":"9(12):1450-1455","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The most common sites for epidural administration in cattle, camels, and buffalos were the sacrococcygeal intervertebral space (S5-Co1) and first intercoccygeal intervertebral space (Co1-Co2). The most frequently used drugs and dosages were"}},{"id":"practrum--bovine-anesthesia--block-decision-tree-clinical-scenario--v3","statement":"IV regional anesthesia (Bier block) ของ distal limb ในโคใต้ tourniquet ให้ complete anesthesia ได้ 22 จาก 23 ราย (96%) ในชุดที่ใช้ 2% lidocaine 15-20 ml แต่มี serious post-surgical complication 2 จาก 15 ราย (13%) จาก extensive thrombosis ของ vein ทั้งหมดที่อยู่ distal ต่อ tourniquet","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2202047","locator":"132(5):227-37","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Complete anesthesia of the treated limb was achieved in 22 out of 23 cases (96%). The successfully treated animals did not express any symptoms of pain for the entire surgical procedure. In 2 out of 15 patients (13%) we observed serious pos"}}]},"practrum--bovine-anesthesia--ga-risks-in-ruminants":{"claims":[{"id":"practrum--bovine-anesthesia--ga-risks-in-ruminants--v1","statement":"ในโค 125 ตัวที่วางยาสลบด้วย xylazine/halothane พบ anesthetic complication 10 ตัว (8%) โดยส่วนใหญ่สัมพันธ์กับ regurgitation ของ ruminal content ร่วมกับหรือไม่ร่วมกับ aspiration และมีโคตายจากการวางยา 3 ตัว ผู้เขียนสรุปว่า general anesthesia ใน ruminant มีความเสี่ยงอย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17422450","locator":"25(9):342-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Anesthetic complications were recorded for ten cattle (8%) in the series and were mainly associated with regurgitation of ruminal contents, with or without aspiration. Three animals died as a result of the anesthetic procedure... it is evid"}},{"id":"practrum--bovine-anesthesia--ga-risks-in-ruminants--v2","statement":"ความเสี่ยงที่สัมพันธ์กับการวางยาสลบใน ruminant สูงกว่าสัตว์ monogastric แต่ถ้าเข้าใจความเสี่ยง วางแผนและเตรียมมาตรการป้องกันเพียงพอ ก็สามารถวางยาสลบ ruminant ในภาคสนามได้ค่อนข้างปลอดภัย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27614776","locator":"32(3):553-570","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Although anesthesia-associated risks are greater in ruminants than monogastrics, ruminants can be anesthetized relatively safely in a field setting if the risks are understood, and adequate planning and precautions are in place."}},{"id":"practrum--bovine-anesthesia--ga-risks-in-ruminants--v3","statement":"Regurgitation ระหว่างวางยาสลบใน Bos นำไปสู่ aspiration pneumonia ได้จริง มีรายงานใน Tibetan yak bull 2 ตัวที่วางยาด้วย ketamine-xylazine-butorphanol เพื่อตอนในท่านอน โดยในโคบ้าน aspiration pneumonia มักเป็นผลตามมาจากการป้อนของเหลวหรือยาทางปาก และจากการ aspiration ระหว่างหัตถการที่วางยาสลบ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29517446","locator":"49(1):242-246","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In these species, aspiration pneumonia is most commonly a sequelae to oral administration of fluids or medications, as well as aspiration during procedures under anesthesia."}}]}},"practrum--rumenotomy":{"practrum--rumenotomy--indications-6-ข้อจากสไลด์":{"claims":[{"id":"practrum--rumenotomy--indications-6-ข้อจากสไลด์--v1","statement":"Traumatic reticuloperitonitis (TRP) เป็นข้อบ่งชี้ที่พบบ่อยที่สุดของ rumenotomy โดยในชุดผู้ป่วย 53 ตัวที่ทำ rumenotomy พบ TRP 31 ตัว รองลงมาคือ bloat 9 ตัว, foreign body 6 ตัว และ choke 5 ตัว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-26331425","locator":"J Am Vet Med Assoc 2015;247(6):659-664, abstract (Results)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Indications for rumenotomy included traumatic reticuloperitonitis (n = 31), bloat (9), foreign body (6), choke (5), and other (2)."}},{"id":"practrum--rumenotomy--indications-6-ข้อจากสไลด์--v2","statement":"การผ่าตัด forestomach ในโคใช้เพื่อวินิจฉัยและรักษาหลายโรค รวมถึง traumatic reticuloperitonitis, perireticular abscess, vagal indigestion และ grain overload","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2200573","locator":"Vet Clin North Am Food Anim Pract 1990;6(2):371-397, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Surgery of the forestomach compartments is performed in bovine practices for the diagnosis and treatment of many diseases, including traumatic reticuloperitonitis, perireticular abscess, vagal indigestion, and grain overload."}}]},"practrum--rumenotomy--surgical-procedure":{"claims":[{"id":"practrum--rumenotomy--surgical-procedure--v1","statement":"Rumenotomy เข้าทาง left flank laparotomy โดยคลำสำรวจ cranial abdomen หา adhesion หรือก้อนก่อน แล้วการเปิดกระเพาะจึงทำให้ตรวจ lumen ของทั้ง rumen และ reticulum ได้อย่างละเอียด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2200573","locator":"Vet Clin North Am Food Anim Pract 1990;6(2):371-397, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Through a left flank laparotomy, the cranial abdomen is first explored by palpation for adhesions or masses. A rumenotomy allows thorough examination of the lumen of the rumen and reticulum."}}]},"practrum--rumenotomy--reticulum-specific-procedures":{"claims":[{"id":"practrum--rumenotomy--reticulum-specific-procedures--v1","statement":"การตรวจร่างกายเพื่อวินิจฉัย TRP มุ่งกระตุ้นให้เกิดเสียง grunt ด้วย foreign body test เช่น back grip, pole test หรือ pain percussion ส่วน radiography เป็น technique of choice สำหรับเห็น metallic foreign body และติดตามผลของแม่เหล็ก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-31982079","locator":"Vet J 2020;255:105424, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The clinical examination is aimed at eliciting a grunt in response to foreign body tests such as back grip, pole test or pain percussion... Radiography is the technique of choice for the visualisation of metallic foreign bodies and for moni"}},{"id":"practrum--rumenotomy--reticulum-specific-procedures--v2","statement":"แนวทางรักษา TRP เริ่มด้วยการให้แม่เหล็กร่วมกับยาปฏิชีวนะก่อน แล้วสงวน rumenotomy ไว้สำหรับรายที่ foreign body ไม่ติดแม่เหล็ก โดยกลุ่มที่ผ่าตัดมีอัตราออกจากโรงพยาบาล 90 เปอร์เซ็นต์ (206 ตัว) เทียบกับกลุ่มรักษาด้วยยา 82 เปอร์เซ็นต์ (232 ตัว)","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30223863","locator":"Acta Vet Scand 2018;60(1):55, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Surgical treatment was significantly more successful than conservative treatment; 90% of 206 operated and 82% of 232 medically-treated cattle were discharged... For practical purposes, cattle suspected of having traumatic reticuloperitoniti"}}]},"practrum--rumenotomy--cow-magnet-hardware-disease-prevention":{"claims":[{"id":"practrum--rumenotomy--cow-magnet-hardware-disease-prevention--v1","statement":"แม่เหล็กที่ให้โคกินไปอยู่ใน reticulum และดึงเศษโลหะแหลมมาติดที่ตัวแม่เหล็ก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19263382","locator":"Schweiz Arch Tierheilkd 2009;151(3):127-131, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"All the cows had numerous thin sharp pieces of metal attached to a magnet in the reticulum, giving the magnet a hedgehog-like appearance."}}]},"practrum--rumenotomy--pre-op-post-op":{"claims":[{"id":"practrum--rumenotomy--pre-op-post-op--v1","statement":"ขนาด flunixin meglumine ที่ใช้ศึกษาในโคคือ 2.2 mg/kg IV และใน Holstein calves พบว่า clearance ที่อายุ 2 เดือนช้ากว่าที่อายุ 8 เดือน ผู้เขียนจึงสรุปว่าการให้ flunixin ในลูกโคอาจต้องปรับ dose และ dosing interval ตามอายุ รวมทั้งยืด withdrawal interval ออกไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29688783","locator":"79(5):568-575","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"At 2 months of age, all calves received an injectable solution of flunixin (2.2 mg/kg, IV)... In calves, the clearance of flunixin at 2 months of age was slower than that at 8 months of age following IV administration. Flunixin administrati"}},{"id":"practrum--rumenotomy--pre-op-post-op--v2","statement":"Procaine penicillin G ขนาด extra-label 24,000 และ 66,000 IU/kg IM วันละครั้ง 5 วันในโคเนื้อรุ่น ต้องใช้ withdrawal 10 วันและ 21 วันตามลำดับ (ขนาดที่ขึ้นทะเบียนในแคนาดาคือ 7,500 IU/kg IM วันละครั้ง withdrawal 5 วัน) และเมื่อให้ 66,000 IU/kg ทาง SC พบ drug deposit ที่ตำแหน่งฉีดนานถึง 10 วัน พร้อม inflammation และ hemorrhage มากกว่าการฉีด IM ขนาดเดียวกัน ผู้เขียนจึงสรุปว่าไม่ควรให้ procaine penicillin G ทาง SC ที่ขนาดสูง และไม่ได้กำหนด withdrawal สำหรับ route SC","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-8269359","locator":"57(4):223-30","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Based on the tissue residue data from this study, the appropriate withdrawal period is ten days for the 24,000 IU/kg body weight dose and 21 days for the 66,000 IU/kg body weight dose when administered intramuscularly... These results sugge"}},{"id":"practrum--rumenotomy--pre-op-post-op--v3","statement":"ในโค 503 ตัวที่เป็น traumatic reticuloperitonitis การรักษาประกอบด้วย magnet ร่วมกับ antibiotic, anti-inflammatory drug และ intravenous fluid โดยทำ rumenotomy เมื่อ foreign body ไม่ติดแม่เหล็กหรือยังทิ่มทะลุ reticulum ผลคือกลุ่มผ่าตัด 206 ตัว discharge 90% ซึ่งสูงกว่ากลุ่มที่รักษาทางยา 232 ตัวที่ 82% อย่างมีนัยสำคัญ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30223863","locator":"60(1):55","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"cattle with a foreign body attached to a magnet were treated conservatively using antibiotics, anti-inflammatory drugs and intravenous fluids... Surgical treatment was significantly more successful than conservative treatment; 90% of 206 op"}}]}},"practrum--penile-deviation":{"practrum--penile-deviation--indications-mechanism":{"claims":[{"id":"practrum--penile-deviation--indications-mechanism--v1","statement":"Teaser bull คือโคเพศผู้ที่ถูกผ่าตัดดัดแปลงระบบสืบพันธุ์ให้เป็นหมัน โดยมีวัตถุประสงค์เพื่อช่วยตรวจจับแม่โคที่เป็นสัด สำหรับกำหนดจังหวะการผสมเทียม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18929951","locator":"Vet Clin North Am Food Anim Pract 2008;24(3):443-453, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A teaser bull is a term describing a bull whose reproductive system has been surgically altered to render him sterile. The purpose of such bulls is to aid in detection of cows in estrus to facilitate when to artificially inseminate."}},{"id":"practrum--penile-deviation--indications-mechanism--v2","statement":"การทำหมัน teaser bull ทำได้ด้วย vasectomy หรือ caudal epididymectomy อย่างใดอย่างหนึ่ง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18929951","locator":"Vet Clin North Am Food Anim Pract 2008;24(3):443-453, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The bull is sterilized by either vasectomy or caudal epididymectomy."}},{"id":"practrum--penile-deviation--indications-mechanism--v3","statement":"นอกเหนือจากการทำหมันแล้ว ยังมีเทคนิคผ่าตัดอื่นที่ทำเพื่อป้องกัน intromission และป้องกันการแพร่โรคติดต่อทางระบบสืบพันธุ์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18929951","locator":"Vet Clin North Am Food Anim Pract 2008;24(3):443-453, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In addition to sterilization, other surgical options are described that prevent intromission and the spread of venereal disease."}},{"id":"practrum--penile-deviation--indications-mechanism--v4","statement":"Paraphimosis เป็นภาวะแทรกซ้อนที่ต้องนึกถึงหลังผ่าตัดเบนอวัยวะเพศใน teaser bull มีรายงานโคที่ทำ penile translocation ร่วมกับ bilateral caudal epididymectomy เกิด paraphimosis ระหว่างใช้งานตรวจสัด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-1500334","locator":"J Am Vet Med Assoc 1992;201(2):325, abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A bull with penile translocation and bilateral caudal epididymectomy developed paraphimosis when used for estrus detection of cows... Paraphimosis should be considered a possible sequela to penile translocation in bulls."}}]},"practrum--penile-deviation--drug-protocol-lecture-2026":{"claims":[{"id":"practrum--penile-deviation--drug-protocol-lecture-2026--v1","statement":"Xylazine 0.1 mg/kg IM เป็นขนาดที่มีรายงานใช้ทำ sedation ในลูกโคก่อนผ่าตัด ซึ่งอยู่ที่ขอบบนของช่วง 0.05-0.1 mg/kg","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-9887947","locator":"J Am Vet Med Assoc 1999;214(1):89-95, abstract (Procedure)","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Calves were sedated with xylazine (0.1 mg/kg [0.045 mg/lb] of body weight, i.m.), and 5 minutes later a 2% solution of lidocaine (0.18 to 0.24 ml/kg) and xylazine (0.05 mg/kg) were administered into the lumbosacral epidural space."}}]}},"practrum--animal-nutrition":{"practrum--animal-nutrition--dmi-calculation":{"claims":[{"id":"practrum--animal-nutrition--dmi-calculation--v1","statement":"DMI ก่อนคลอดที่ลดลงใช้คัดกรองแม่โคที่เสี่ยงต่อ metritis ได้: ทุก 1 kg ของ DMI ที่ลดลงในสัปดาห์ก่อนคลอด แม่โคมีโอกาสถูกวินิจฉัยว่าเป็น severe metritis เพิ่มขึ้นเกือบ 3 เท่า และแม่โคกลุ่มนี้กินน้อยลงและใช้เวลากินสั้นลงตั้งแต่ประมาณ 2 สัปดาห์ก่อนแสดงอาการทางคลินิก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-17582105","locator":"J Dairy Sci 2007;90(7):3220-33, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For every 10-min decrease in average daily feeding time during the week before calving, the odds of severe metritis increased by 1.72, and for every 1-kg decrease in DMI during this period, cows were nearly 3 times more likely to be diagnos"}}]},"practrum--animal-nutrition--nutritional-values":{"claims":[{"id":"practrum--animal-nutrition--nutritional-values--v1","statement":"NDF ถูกใช้เป็นตัวแทนของ fill effect ในการทำนาย DMI: ในแบบจำลอง physical regulation ปริมาณการกินแปรผกผัน (reciprocal) กับ fill effect ของอาหาร ดังนั้นสูตรอาหารที่ NDF สูงขึ้นจะกด DMI ลง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3583960","locator":"J Anim Sci 1987;64(5):1548-58, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These equations indicate that intake is a linear function of animal characteristics, such as body weight and production level, and a reciprocal function of feed characteristics, such as fill effect and energy content. Theoretical equations "}}]},"practrum--animal-nutrition--r-c-ratio-particle-size":{"claims":[{"id":"practrum--animal-nutrition--r-c-ratio-particle-size--v1","statement":"SARA เกิดจากการให้ non-structural carbohydrate มากเกินร่วมกับ coarse fiber ในสูตรไม่พอ (คือ R:C เอียงไปทาง concentrate) ผลตามมาที่รายงานไว้ได้แก่ DMI ลดลง, fiber digestion ลดลง, milk fat depression, ท้องเสีย, laminitis และ liver abscess โดยการสำรวจพบอุบัติการณ์ในโคนมระยะ early และ mid lactation ประมาณ 19-26%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18329918","locator":"Vet J 2008;176(1):21-31, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Surveys suggested an incidence of SARA of between 19% and 26% in early and mid-lactation dairy cows. Causes of SARA include feeding excessive amounts of non-structural carbohydrates and highly fermentable forages, and insufficient dietary c"}},{"id":"practrum--animal-nutrition--r-c-ratio-particle-size--v2","statement":"เกณฑ์เชิงตัวเลขของ SARA จาก meta-analysis คือควรหลีกเลี่ยงสองเหตุการณ์ ได้แก่ ค่าเฉลี่ย ruminal pH รายวันต่ำกว่า 6.16 และช่วงที่ ruminal pH ต่ำกว่า 5.8 นานเกิน 5.24 ชั่วโมงต่อวัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18420634","locator":"J Dairy Sci 2008;91(5):2046-66, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Results of this study showed that to minimize the risk of SARA, the following events should be avoided: 1) a daily mean ruminal pH lower than 6.16, and 2) a time period in which ruminal pH is <5.8 for more than 5.24 h/d."}},{"id":"practrum--animal-nutrition--r-c-ratio-particle-size--v3","statement":"ความต้องการ physically effective NDF ของโคนมให้ผลผลิตสูงที่กิน TMR แบบ ad libitum ประมาณ 19% ของ ration DM (หรือ 4.1 kg/วัน หรือ 0.6 kg ต่อ BW 100 kg) เพื่อรักษา ruminal pH เฉลี่ยไว้ที่ประมาณ 6.0 เมื่อวัด peNDF จากสัดส่วน DM ที่ค้างบนตะแกรง 1.18 mm","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16428635","locator":"J Dairy Sci 2006;89(2):651-68, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Using peNDF(> 1.18) approach, the requirements for physically effective fiber in high-yielding dairy cows fed TMR in an ad libitum intake were estimated to be about 19% of ration DM or 4.1 kg/d or 0.6 kg/100 kg of body weight to maintain a "}},{"id":"practrum--animal-nutrition--r-c-ratio-particle-size--v4","statement":"Penn State Particle Separator รุ่นปรับปรุงเพิ่มตะแกรงชั้นที่สาม และวิธีเขย่าที่แนะนำคือความถี่ตั้งแต่ 1.1 Hz ขึ้นไป ด้วยระยะชัก (stroke length) 17 ซม เพราะการเขย่าช้ากว่านั้น (0.9 Hz) ทำให้มีวัสดุค้างบนตะแกรง 19.0 mm มากเกินจริง และความชื้นของตัวอย่างมีผลต่อผลการแยกในข้าวโพดหมัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12778598","locator":"J Dairy Sci 2003;86(5):1858-63, Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"We suggest using a third sieve and shaking at 1.1 Hz or greater with a stroke length of 17 cm when using the Penn State Particle Separator to analyze forage particle size."}}]}}};
