export const CORRECTIONS = {"practrum--animal-nutrition--r-c-ratio-particle-size":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า \"peNDF (physically effective NDF) ≥21% ของ DM\" โดยไม่ระบุว่าใช้ตะแกรงขนาดใดเป็น basis","evidenceSays":"งานทดลองในโครีดนมระยะต้น (J Dairy Sci 2006, PMID 16428635, doi:10.3168/jds.S0022-0302(06)72129-4) ระบุความต้องการ peNDF ประมาณ 19% ของ ration DM (4.1 kg/วัน หรือ 0.6 kg ต่อ BW 100 kg) เพื่อรักษา ruminal pH เฉลี่ยที่ ~6.0 เมื่อวัดจากสัดส่วน DM ที่ค้างบนตะแกรง 1.18 mm ขณะที่ meta-analysis ของกลุ่มเดียวกันบน basis เดียวกันให้ 30-33% และ peNDF ที่วัดจากตะแกรง >8 mm ทำนาย ruminal pH ได้แม่นยำน้อยกว่า (R2 = 0.27 เทียบกับ 0.67)","examAdvice":"ถ้าข้อสอบให้เลือกตัวเลข ให้ตอบ ≥21% ตามเลกเชอร์ แต่ถ้าเป็นข้อเขียนให้ระบุ basis ของตะแกรงกำกับไว้ด้วยเสมอ","sourceRef":"PMID 16428635 / doi:10.3168/jds.S0022-0302(06)72129-4 — Effects of physically effective fiber on digestive processes and milk fat content in early lactating dairy cows fed total mixed rations"}],"practrum--bovine-anesthesia--sedation-alpha-2-agonist":[{"severity":"contradicts","lectureSays":"โน้ตเขียนว่า \"Phase 1 (vasoconstriction): BP สูง → reflex bradycardia, CO ลด\"","evidenceSays":"การศึกษา hemodynamic ของ xylazine ขนาด sedative ในลูกโค (PMID 525899) พบว่า heart rate, cardiac output และ arterial blood pressure ลดลง ขณะที่ total peripheral resistance เพิ่มขึ้น โดยระบุชัดว่าไม่พบ hypertensive response คำอธิบาย biphasic hypertension เป็นภาพคลาสสิกจากสัตว์ชนิดอื่น","examAdvice":"ถ้าข้อสอบถามกลไก biphasic ให้ตอบ BP สูงแล้ว reflex bradycardia ตามเลกเชอร์ แต่ถ้าเป็นข้อเขียนเรื่องผลในโคโดยเฉพาะ ให้ระบุว่า TPR เพิ่มแต่ BP ไม่ได้สูงขึ้น","sourceRef":"PMID 525899 — Hemodynamic effects of xylazine in the calf"}],"practrum--cow-restraint--low-stress-handling-temple-grandin":[{"severity":"contradicts","lectureSays":"โน้ตเขียนว่า \"Flight zone: ~5-15 m radius depending on cow domestication\"","evidenceSays":"WOAH Terrestrial Animal Health Code บทที่ 7.5 (Slaughter of Animals) ระบุว่าขนาด flight zone ไม่คงที่ ขึ้นกับชนิดสัตว์ ตัวสัตว์แต่ละตัว และประสบการณ์ที่เคยสัมผัสกับคน โดยกว้างตั้งแต่ 1 เมตรจนถึงหลายเมตร สัตว์ที่เลี้ยงใกล้ชิดคน (tame) มี flight zone เล็กกว่า และไม่พบแหล่งตีพิมพ์ที่ให้ตัวเลข 5-15 m","examAdvice":"ถ้าข้อสอบให้เลือกตัวเลข ให้ตอบ 5-15 m ตามที่เรียน แต่จำไว้ว่าค่าจริงเริ่มได้ตั้งแต่ ~1 เมตรและขึ้นกับความคุ้นเคยของโค","sourceRef":"WOAH Terrestrial Animal Health Code, Chapter 7.5 Slaughter of Animals"}],"practrum--dehorning--disbudding-methods-comparison":[{"severity":"contradicts","lectureSays":"ตาราง Disbudding Methods Comparison ระบุ Pros ของ 50% CaCl2 caustic paste ว่า \"Painless if used early\"","evidenceSays":"RCT ในลูกโคนม (J Dairy Sci 2017, PMID 28551190, doi:10.3168/jds.2017-12724) ที่ลูกโคทุกตัวได้รับ meloxicam อยู่แล้ว พบว่า caustic paste disbudding ทำให้เจ็บเฉียบพลัน (acute pain) นานอย่างน้อย 180 นาที และความเจ็บลดลงได้ด้วย cornual nerve block ผู้วิจัยจึงแนะนำให้ลูกโคที่ทำ caustic paste ได้รับทั้ง local anaesthetic แบบ cornual nerve block และ NSAID","examAdvice":"ถ้าข้อสอบถามข้อดีของ caustic paste ตามเลกเชอร์ให้ตอบ painless if used early แต่ถ้าเป็นข้อเขียนหรือคำถามเชิงสวัสดิภาพสัตว์ ให้เขียนว่าเจ็บจริงและต้องมี cornual block + NSAID","sourceRef":"PMID 28551190 / doi:10.3168/jds.2017-12724 — Clinical trial of local anesthetic protocols for acute pain associated with caustic paste disbudding in dairy calves"}],"practrum--hoof-trim--hoof-anatomy-claw-zones":[{"severity":"narrows","lectureSays":"ตาราง claw zones ระบุ zone 4 ว่า \"Sole-heel junction (Rusterholz)\" เป็นตำแหน่ง sole ulcer","evidenceSays":"บทความทบทวน Pododermatitis circumscripta (PMID 16955800, doi:10.1892/0891-6640(2006)20[805:ropcuo]2.0.co;2) ระบุว่าตำแหน่งที่รายงานบ่อยที่สุดคือรอยต่อระหว่าง axial heel กับ sole พบบ่อยที่สุดที่ lateral claw ของขาหลัง มักเกิดทั้งสองข้าง และมีอัตราการกลับเป็นซ้ำสูง","examAdvice":"ตอบ zone 4 sole-heel junction ตามเลกเชอร์ได้ ถ้าเป็นข้อเขียนให้เติมคำว่า axial เพื่อความแม่นยำ","sourceRef":"PMID 16955800 / doi:10.1892/0891-6640(2006)20[805:ropcuo]2.0.co;2 — Review of Pododermatitis circumscripta (ulceration of the sole) in dairy cows"}],"practrum--hoof-trim--routine-care-disease-categories":[{"severity":"contradicts","lectureSays":"โน้ตสะกดชื่อโรคว่า \"Pododermatitis circumcripta\"","evidenceSays":"ชื่อที่ถูกต้องคือ \"Pododermatitis circumscripta\" ตามชื่อบทความทบทวน Review of Pododermatitis circumscripta (ulceration of the sole) in dairy cows (PMID 16955800) ซึ่งยังระบุตำแหน่งเจาะจงเป็นรอยต่อ axial heel กับ sole ของ lateral claw ขาหลัง","examAdvice":"เนื้อหาตอบตามเลกเชอร์ได้ทั้งหมด แค่เวลาเขียนชื่อโรคให้สะกดว่า Pododermatitis circumscripta","sourceRef":"PMID 16955800 / doi:10.1892/0891-6640(2006)20[805:ropcuo]2.0.co;2 — Review of Pododermatitis circumscripta (ulceration of the sole) in dairy cows"}],"practrum--rumenotomy--pre-op-post-op":[{"severity":"narrows","lectureSays":"โน้ตเขียนว่า \"Procaine penicillin 22,000-66,000 U/kg IM/SC (NOT IV) ≥ 3 วัน\" โดยให้ SC เป็นทางเลือกเท่ากับ IM และไม่ระบุ withdrawal","evidenceSays":"งาน depletion ในโคเนื้อรุ่น (PMID 8269359) พบว่าขนาด extra-label 24,000 และ 66,000 IU/kg IM วันละครั้ง 5 วัน ต้องใช้ withdrawal 10 วันและ 21 วันตามลำดับ เทียบกับขนาดที่ขึ้นทะเบียน 7,500 IU/kg IM ซึ่ง withdrawal เพียง 5 วัน และเมื่อให้ 66,000 IU/kg ทาง SC พบ drug deposit ที่ตำแหน่งฉีดนานถึง 10 วัน ร่วมกับ inflammation และ hemorrhage","examAdvice":"ข้อสอบให้ตอบ dose และ route ตามเลกเชอร์ (IM/SC ไม่ใช่ IV) แต่ถ้าเป็นข้อเขียนหรือถามความปลอดภัยอาหาร ให้เลือก IM และระบุว่าเป็น extra-label ที่ดัน withdrawal เป็น 10-21 วัน","sourceRef":"PMID 8269359 — Depletion of intramuscularly and subcutaneously injected procaine penicillin G from tissues and plasma of yearling beef steers"}]};
